SELECT t.target_time, 'loucka_reconstruction' AS source_database, MAX(CASE WHEN a.dateTime=t.target_time-900 THEN a.dateTime END) AS offset_m900, MAX(CASE WHEN a.dateTime=t.target_time-600 THEN a.dateTime END) AS offset_m600, MAX(CASE WHEN a.dateTime=t.target_time-300 THEN a.dateTime END) AS offset_m300, MAX(CASE WHEN a.dateTime=t.target_time+300 THEN a.dateTime END) AS offset_p300, MAX(CASE WHEN a.dateTime=t.target_time+600 THEN a.dateTime END) AS offset_p600, MAX(CASE WHEN a.dateTime=t.target_time+900 THEN a.dateTime END) AS offset_p900 FROM (SELECT 1556184600 AS target_time UNION ALL SELECT 1556184900 UNION ALL SELECT 1556185200 UNION ALL SELECT 1598789100 UNION ALL SELECT 1598789400 UNION ALL SELECT 1603181700 UNION ALL SELECT 1603182000 UNION ALL SELECT 1603185600 UNION ALL SELECT 1603185900 UNION ALL SELECT 1603188600 UNION ALL SELECT 1607100600 UNION ALL SELECT 1607102700 UNION ALL SELECT 1607103000 UNION ALL SELECT 1607212800 UNION ALL SELECT 1607213100 UNION ALL SELECT 1607215800 UNION ALL SELECT 1607217300 UNION ALL SELECT 1607311200 UNION ALL SELECT 1607314800 UNION ALL SELECT 1607317200 UNION ALL SELECT 1607524500 UNION ALL SELECT 1607524800 UNION ALL SELECT 1607525100 UNION ALL SELECT 1607525400) t LEFT JOIN `loucka_reconstruction`.archive a ON a.dateTime IN (t.target_time-900,t.target_time-600,t.target_time-300,t.target_time+300,t.target_time+600,t.target_time+900) GROUP BY t.target_time
UNION ALL
